<div class="container">
  <header>
    <h1>Nine Decades of Oscar-Winning Scores</h1>
    <p class="subtitle">A Historical Trend Analysis (1934–2026) | 93 Ceremonies Analyzed</p>
  </header>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-value">79</div>
      <div class="kpi-label">Unique Composers</div>
    </div>
